using Orchestration.API.Engineering.Contracts;using Orchestration.API.Engineering.Intelligence;
namespace Orchestration.API.Tests.Engineering.Intelligence;
public sealed class EngineeringIntelligenceAssemblerTests
{
 [Fact]public void Assembler_is_deterministic_and_preserves_partial_sources(){var now=DateTimeOffset.Parse("2026-09-01T00:00:00Z");var input=new UnifiedProductIntelligence("1.0","intel-1",new("identity-1","EYE HEAD","100",IntelligenceConfidence.Deterministic,["100"],["identifier agreement"]),[Envelope(EngineeringSource.Sap,StandardStatus.PartialSuccess,now),Envelope(EngineeringSource.Teamcenter,StandardStatus.Success,now)],[],[],[],StandardStatus.PartialSuccess,now);var sut=new EngineeringIntelligenceInvestigationAssembler();var a=sut.Assemble(input);var b=sut.Assemble(input with{Sources=input.Sources.Reverse().ToArray()});Assert.Equal(a,b);Assert.Equal("1.0",a.ContractVersion);Assert.Equal(2,a.Sources.Count);Assert.Contains(a.Sources,x=>x.Source==EngineeringSource.Sap&&x.Status==SourceExtractionStatus.Partial);Assert.All(a.Entities,x=>Assert.NotNull(x.Provenance));}
 static SourceIntelligenceEnvelope Envelope(EngineeringSource source,StandardStatus status,DateTimeOffset now)=>new(source,status,new($"candidate-{source}",source,$"id-{source}",$"{source} representation","part",null,null,null,null,MatchCategory.VerifiedIdentifierMatch,"test",ConfidenceClass.Verified,[],new Dictionary<string,string?>(),new(ProvenanceKind.DeterministicTestFixture,"test",now),true),new UnavailableTypedEvidence(source,EvidenceAvailability.NotObserved,"test"),[],[],[],new(ProvenanceKind.DeterministicTestFixture,"test",now));
}
